CREATE DATABASE qinghe_mart CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE qinghe_mart;
CREATE TABLE `regions` (`region_id` VARCHAR(8) NOT NULL COMMENT '大区编号',`region_name` VARCHAR(32) NULL COMMENT '大区名称',`manager_name` VARCHAR(32) NULL COMMENT '大区经理',PRIMARY KEY (`region_id`)) COMMENT='大区';
CREATE TABLE `stores` (`store_id` VARCHAR(8) NOT NULL COMMENT '门店编号',`store_name` VARCHAR(64) NULL COMMENT '门店名称',`region_id` VARCHAR(8) NULL COMMENT '所属大区',`city` VARCHAR(32) NULL COMMENT '城市',`address` VARCHAR(128) NULL COMMENT '地址',`store_type` VARCHAR(8) NULL COMMENT '门店类型：标准店/社区店/旗舰店',`area_sqm` DECIMAL(8, 2) NULL COMMENT '经营面积（平方米）',`opened_on` DATE NULL COMMENT '开业日期',`closed_on` DATE NULL COMMENT '闭店日期，营业中为空',`status` VARCHAR(8) NULL COMMENT '状态：营业/装修/闭店',`manager_emp_id` VARCHAR(8) NULL COMMENT '店长工号',PRIMARY KEY (`store_id`)) COMMENT='门店';
CREATE TABLE `employees` (`emp_id` VARCHAR(8) NOT NULL COMMENT '工号',`emp_name` VARCHAR(32) NULL COMMENT '姓名',`store_id` VARCHAR(8) NULL COMMENT '所在门店，总部员工为空',`position` VARCHAR(16) NULL COMMENT '岗位：店长/收银/理货/采购/仓管',`hired_on` DATE NULL COMMENT '入职日期',`left_on` DATE NULL COMMENT '离职日期',`phone_masked` VARCHAR(16) NULL COMMENT '手机号（脱敏）',PRIMARY KEY (`emp_id`)) COMMENT='员工';
CREATE TABLE `warehouses` (`wh_id` VARCHAR(8) NOT NULL COMMENT '仓库编号',`wh_name` VARCHAR(64) NULL COMMENT '仓库名称',`city` VARCHAR(32) NULL COMMENT '城市',`wh_type` VARCHAR(8) NULL COMMENT '仓库类型：常温/冷链',PRIMARY KEY (`wh_id`)) COMMENT='仓库';
CREATE TABLE `member_levels` (`level_code` VARCHAR(8) NOT NULL COMMENT '等级代码',`level_name` VARCHAR(16) NULL COMMENT '等级名称：普通/银卡/金卡/黑卡',`min_points` INTEGER NULL COMMENT '达到该等级所需积分',`discount_rate` DECIMAL(4, 2) NULL COMMENT '会员折扣率',PRIMARY KEY (`level_code`)) COMMENT='会员等级';
CREATE TABLE `members` (`member_id` VARCHAR(16) NOT NULL COMMENT '会员编号',`member_name` VARCHAR(32) NULL COMMENT '姓名',`gender` VARCHAR(4) NULL COMMENT '性别',`birth_month` INTEGER NULL COMMENT '生日月份',`mobile_masked` VARCHAR(16) NULL COMMENT '手机号（脱敏）',`level_code` VARCHAR(8) NULL COMMENT '会员等级',`points` INTEGER NULL COMMENT '当前积分',`city` VARCHAR(32) NULL COMMENT '常住城市',`register_store_id` VARCHAR(8) NULL COMMENT '注册门店',`register_channel` VARCHAR(8) NULL COMMENT '注册渠道：门店/小程序/APP',`registered_at` DATETIME NULL COMMENT '注册时间',`last_order_at` DATETIME NULL COMMENT '最近下单时间',`status` VARCHAR(8) NULL COMMENT '状态：正常/冻结/注销',PRIMARY KEY (`member_id`)) COMMENT='会员';
CREATE TABLE `categories` (`category_id` VARCHAR(8) NOT NULL COMMENT '品类编号',`category_name` VARCHAR(32) NULL COMMENT '品类名称',`parent_id` VARCHAR(8) NULL COMMENT '上级品类，一级品类为空',`level` INTEGER NULL COMMENT '层级：1 一级，2 二级',PRIMARY KEY (`category_id`)) COMMENT='商品品类';
CREATE TABLE `brands` (`brand_id` VARCHAR(8) NOT NULL COMMENT '品牌编号',`brand_name` VARCHAR(64) NULL COMMENT '品牌名称',`is_private_label` INTEGER NULL COMMENT '是否自有品牌：1 是 0 否',PRIMARY KEY (`brand_id`)) COMMENT='品牌';
CREATE TABLE `suppliers` (`supplier_id` VARCHAR(8) NOT NULL COMMENT '供应商编号',`supplier_name` VARCHAR(64) NULL COMMENT '供应商名称',`city` VARCHAR(32) NULL COMMENT '所在城市',`settle_days` INTEGER NULL COMMENT '账期（天）',`contact_masked` VARCHAR(16) NULL COMMENT '联系电话（脱敏）',`status` VARCHAR(8) NULL COMMENT '状态：合作中/暂停/终止',PRIMARY KEY (`supplier_id`)) COMMENT='供应商';
CREATE TABLE `products` (`sku` VARCHAR(16) NOT NULL COMMENT '商品编码',`product_name` VARCHAR(64) NULL COMMENT '商品名称',`barcode` VARCHAR(20) NULL COMMENT '条码',`category_id` VARCHAR(8) NULL COMMENT '二级品类',`brand_id` VARCHAR(8) NULL COMMENT '品牌',`supplier_id` VARCHAR(8) NULL COMMENT '主供应商',`spec` VARCHAR(32) NULL COMMENT '规格',`unit` VARCHAR(8) NULL COMMENT '销售单位',`shelf_life_days` INTEGER NULL COMMENT '保质期（天）',`storage_type` VARCHAR(8) NULL COMMENT '储存方式：常温/冷藏/冷冻',`list_price` DECIMAL(10, 2) NULL COMMENT '零售价',`member_price` DECIMAL(10, 2) NULL COMMENT '会员价',`cost_price` DECIMAL(10, 2) NULL COMMENT '进价',`is_fresh` INTEGER NULL COMMENT '是否生鲜：1 是 0 否',`launched_on` DATE NULL COMMENT '上架日期',`delisted_on` DATE NULL COMMENT '下架日期',`status` VARCHAR(8) NULL COMMENT '状态：在售/停售/淘汰',`tax_rate` DECIMAL(4, 2) NULL COMMENT '税率',PRIMARY KEY (`sku`)) COMMENT='商品';
CREATE TABLE `purchase_orders` (`po_no` VARCHAR(20) NOT NULL COMMENT '采购单号',`supplier_id` VARCHAR(8) NULL COMMENT '供应商',`wh_id` VARCHAR(8) NULL COMMENT '收货仓库',`ordered_at` DATETIME NULL COMMENT '下单时间',`expected_on` DATE NULL COMMENT '预计到货日期',`status` VARCHAR(8) NULL COMMENT '状态：草稿/已下单/部分到货/已完成/已取消',`total_amount` DECIMAL(12, 2) NULL COMMENT '采购总额',`buyer_emp_id` VARCHAR(8) NULL COMMENT '采购员工号',PRIMARY KEY (`po_no`)) COMMENT='采购单';
CREATE TABLE `purchase_order_items` (`po_no` VARCHAR(20) NOT NULL COMMENT '采购单号',`line_no` INTEGER NOT NULL COMMENT '行号',`sku` VARCHAR(16) NULL COMMENT '商品编码',`qty` INTEGER NULL COMMENT '采购数量',`unit_cost` DECIMAL(10, 2) NULL COMMENT '采购单价',PRIMARY KEY (`po_no`,`line_no`)) COMMENT='采购单明细';
CREATE TABLE `receipts` (`receipt_no` VARCHAR(20) NOT NULL COMMENT '入库单号',`po_no` VARCHAR(20) NULL COMMENT '来源采购单',`wh_id` VARCHAR(8) NULL COMMENT '入库仓库',`received_at` DATETIME NULL COMMENT '入库时间',`status` VARCHAR(8) NULL COMMENT '状态：待验收/已入库',PRIMARY KEY (`receipt_no`)) COMMENT='入库单';
CREATE TABLE `receipt_items` (`receipt_no` VARCHAR(20) NOT NULL COMMENT '入库单号',`line_no` INTEGER NOT NULL COMMENT '行号',`sku` VARCHAR(16) NULL COMMENT '商品编码',`qty_received` INTEGER NULL COMMENT '实收数量',`qty_rejected` INTEGER NULL COMMENT '拒收数量',`batch_no` VARCHAR(20) NULL COMMENT '批次号',`produced_on` DATE NULL COMMENT '生产日期',PRIMARY KEY (`receipt_no`,`line_no`)) COMMENT='入库明细';
CREATE TABLE `transfers` (`transfer_no` VARCHAR(20) NOT NULL COMMENT '调拨单号',`from_wh_id` VARCHAR(8) NULL COMMENT '发货仓库',`to_store_id` VARCHAR(8) NULL COMMENT '收货门店',`shipped_at` DATETIME NULL COMMENT '发货时间',`arrived_at` DATETIME NULL COMMENT '到店时间',`status` VARCHAR(8) NULL COMMENT '状态：在途/已到店/已取消',PRIMARY KEY (`transfer_no`)) COMMENT='调拨单';
CREATE TABLE `transfer_items` (`transfer_no` VARCHAR(20) NOT NULL COMMENT '调拨单号',`line_no` INTEGER NOT NULL COMMENT '行号',`sku` VARCHAR(16) NULL COMMENT '商品编码',`qty` INTEGER NULL COMMENT '调拨数量',PRIMARY KEY (`transfer_no`,`line_no`)) COMMENT='调拨明细';
CREATE TABLE `inventory_daily` (`snapshot_date` DATE NOT NULL COMMENT '快照日期',`location_type` VARCHAR(8) NOT NULL COMMENT '库存地点类型：仓库/门店',`location_id` VARCHAR(8) NOT NULL COMMENT '仓库或门店编号',`sku` VARCHAR(16) NOT NULL COMMENT '商品编码',`on_hand_qty` INTEGER NULL COMMENT '日末库存数量',`on_hand_cost` DECIMAL(12, 2) NULL COMMENT '日末库存成本',PRIMARY KEY (`snapshot_date`,`location_type`,`location_id`,`sku`)) COMMENT='每日库存快照';
CREATE TABLE `stocktakes` (`stocktake_no` VARCHAR(20) NOT NULL COMMENT '盘点单号',`store_id` VARCHAR(8) NULL COMMENT '盘点门店',`counted_on` DATE NULL COMMENT '盘点日期',`status` VARCHAR(8) NULL COMMENT '状态：盘点中/已确认',PRIMARY KEY (`stocktake_no`)) COMMENT='盘点单';
CREATE TABLE `stocktake_items` (`stocktake_no` VARCHAR(20) NOT NULL COMMENT '盘点单号',`sku` VARCHAR(16) NOT NULL COMMENT '商品编码',`book_qty` INTEGER NULL COMMENT '账面数量',`counted_qty` INTEGER NULL COMMENT '实盘数量',PRIMARY KEY (`stocktake_no`,`sku`)) COMMENT='盘点明细';
CREATE TABLE `sales_orders` (`order_no` VARCHAR(20) NOT NULL COMMENT '订单号',`store_id` VARCHAR(8) NULL COMMENT '成交门店',`member_id` VARCHAR(16) NULL COMMENT '会员，散客为空',`channel` VARCHAR(8) NULL COMMENT '渠道：门店/小程序/外卖',`cashier_emp_id` VARCHAR(8) NULL COMMENT '收银员工号，线上订单为空',`ordered_at` DATETIME NULL COMMENT '下单时间',`paid_at` DATETIME NULL COMMENT '支付时间',`status` VARCHAR(8) NULL COMMENT '状态：待支付/已完成/已取消',`gross_amount` DECIMAL(12, 2) NULL COMMENT '商品原价合计',`discount_amount` DECIMAL(12, 2) NULL COMMENT '促销优惠',`coupon_amount` DECIMAL(12, 2) NULL COMMENT '优惠券抵扣',`pay_amount` DECIMAL(12, 2) NULL COMMENT '实付金额',`is_delivery` INTEGER NULL COMMENT '是否配送到家：1 是 0 否',PRIMARY KEY (`order_no`)) COMMENT='销售订单';
CREATE TABLE `sales_order_items` (`order_no` VARCHAR(20) NOT NULL COMMENT '订单号',`line_no` INTEGER NOT NULL COMMENT '行号',`sku` VARCHAR(16) NULL COMMENT '商品编码',`qty` DECIMAL(10, 2) NULL COMMENT '数量（称重商品可为小数）',`list_price` DECIMAL(10, 2) NULL COMMENT '零售价',`deal_price` DECIMAL(10, 2) NULL COMMENT '成交单价',`discount_amount` DECIMAL(10, 2) NULL COMMENT '行优惠',`promotion_id` VARCHAR(16) NULL COMMENT '参与的促销活动',PRIMARY KEY (`order_no`,`line_no`)) COMMENT='销售订单明细';
CREATE TABLE `payments` (`payment_no` VARCHAR(24) NOT NULL COMMENT '支付流水号',`order_no` VARCHAR(20) NULL COMMENT '订单号',`pay_method` VARCHAR(8) NULL COMMENT '支付方式：现金/微信/支付宝/储值卡',`amount` DECIMAL(12, 2) NULL COMMENT '支付金额',`paid_at` DATETIME NULL COMMENT '支付时间',PRIMARY KEY (`payment_no`)) COMMENT='支付记录';
CREATE TABLE `refunds` (`refund_no` VARCHAR(20) NOT NULL COMMENT '退款单号',`order_no` VARCHAR(20) NULL COMMENT '原订单号',`refund_type` VARCHAR(8) NULL COMMENT '退款类型：整单/部分',`applied_at` DATETIME NULL COMMENT '申请时间',`approved_at` DATETIME NULL COMMENT '审核通过时间',`refund_amount` DECIMAL(12, 2) NULL COMMENT '退款金额',`reason` VARCHAR(64) NULL COMMENT '退款原因',`status` VARCHAR(8) NULL COMMENT '状态：待审核/已退款/已驳回',PRIMARY KEY (`refund_no`)) COMMENT='退款单';
CREATE TABLE `refund_items` (`refund_no` VARCHAR(20) NOT NULL COMMENT '退款单号',`line_no` INTEGER NOT NULL COMMENT '行号',`sku` VARCHAR(16) NULL COMMENT '商品编码',`qty` DECIMAL(10, 2) NULL COMMENT '退货数量',`amount` DECIMAL(10, 2) NULL COMMENT '退款金额',PRIMARY KEY (`refund_no`,`line_no`)) COMMENT='退款明细';
CREATE TABLE `promotions` (`promotion_id` VARCHAR(16) NOT NULL COMMENT '活动编号',`promotion_name` VARCHAR(64) NULL COMMENT '活动名称',`promo_type` VARCHAR(16) NULL COMMENT '类型：满减/折扣/第二件半价',`start_at` DATETIME NULL COMMENT '开始时间',`end_at` DATETIME NULL COMMENT '结束时间',`store_scope` VARCHAR(16) NULL COMMENT '适用门店范围：全部/指定大区',PRIMARY KEY (`promotion_id`)) COMMENT='促销活动';
CREATE TABLE `promotion_products` (`promotion_id` VARCHAR(16) NOT NULL COMMENT '活动编号',`sku` VARCHAR(16) NOT NULL COMMENT '商品编码',PRIMARY KEY (`promotion_id`,`sku`)) COMMENT='促销商品';
CREATE TABLE `coupons` (`coupon_id` VARCHAR(16) NOT NULL COMMENT '券编号',`coupon_name` VARCHAR(64) NULL COMMENT '券名称',`face_value` DECIMAL(8, 2) NULL COMMENT '面额',`threshold_amount` DECIMAL(8, 2) NULL COMMENT '使用门槛',`valid_from` DATE NULL COMMENT '有效期开始',`valid_to` DATE NULL COMMENT '有效期结束',PRIMARY KEY (`coupon_id`)) COMMENT='优惠券';
CREATE TABLE `coupon_issues` (`issue_no` VARCHAR(24) NOT NULL COMMENT '发放编号',`coupon_id` VARCHAR(16) NULL COMMENT '券编号',`member_id` VARCHAR(16) NULL COMMENT '领券会员',`issued_at` DATETIME NULL COMMENT '发放时间',`used_at` DATETIME NULL COMMENT '核销时间',`used_order_no` VARCHAR(20) NULL COMMENT '核销订单',`status` VARCHAR(8) NULL COMMENT '状态：未使用/已使用/已过期',PRIMARY KEY (`issue_no`)) COMMENT='优惠券发放';
CREATE TABLE `deliveries` (`delivery_no` VARCHAR(20) NOT NULL COMMENT '配送单号',`order_no` VARCHAR(20) NULL COMMENT '订单号',`rider_id` VARCHAR(8) NULL COMMENT '骑手',`dispatched_at` DATETIME NULL COMMENT '出发时间',`promised_at` DATETIME NULL COMMENT '承诺送达时间',`delivered_at` DATETIME NULL COMMENT '实际送达时间',`distance_km` DECIMAL(6, 2) NULL COMMENT '配送距离（公里）',`delivery_fee` DECIMAL(8, 2) NULL COMMENT '配送费',`status` VARCHAR(8) NULL COMMENT '状态：配送中/已送达/异常',PRIMARY KEY (`delivery_no`)) COMMENT='配送单';
CREATE TABLE `riders` (`rider_id` VARCHAR(8) NOT NULL COMMENT '骑手编号',`rider_name` VARCHAR(32) NULL COMMENT '姓名',`partner_company` VARCHAR(64) NULL COMMENT '所属配送商',PRIMARY KEY (`rider_id`)) COMMENT='骑手';
CREATE TABLE `price_changes` (`change_id` VARCHAR(20) NOT NULL COMMENT '调价单号',`sku` VARCHAR(16) NULL COMMENT '商品编码',`store_id` VARCHAR(8) NULL COMMENT '门店，全国统一调价为空',`old_price` DECIMAL(10, 2) NULL COMMENT '原价',`new_price` DECIMAL(10, 2) NULL COMMENT '新价',`effective_at` DATETIME NULL COMMENT '生效时间',`reason` VARCHAR(32) NULL COMMENT '原因：促销/成本变动/临期',PRIMARY KEY (`change_id`)) COMMENT='调价记录';
CREATE TABLE `dim_date` (`date_key` INTEGER NOT NULL COMMENT '日期键 yyyymmdd',`cal_date` DATE NULL COMMENT '日期',`year` INTEGER NULL COMMENT '年',`month` INTEGER NULL COMMENT '月',`week_of_year` INTEGER NULL COMMENT '年内周序号',`is_holiday` INTEGER NULL COMMENT '是否节假日',PRIMARY KEY (`date_key`)) COMMENT='日期维表';
CREATE TABLE `ods_sync_log` (`id` INTEGER NOT NULL COMMENT '自增编号',`table_name` VARCHAR(64) NULL COMMENT '同步的表',`synced_at` DATETIME NULL COMMENT '同步时间',`row_count` INTEGER NULL COMMENT '同步行数',PRIMARY KEY (`id`)) COMMENT='数据同步日志（技术表）';
CREATE TABLE `tmp_sales_orders_bak_20250101` (`order_no` VARCHAR(20) NOT NULL COMMENT '订单号',`store_id` VARCHAR(8) NULL COMMENT '门店',`member_id` VARCHAR(16) NULL COMMENT '会员',`ordered_at` DATETIME NULL COMMENT '下单时间',`status` VARCHAR(8) NULL COMMENT '状态',`pay_amount` DECIMAL(12, 2) NULL COMMENT '实付金额',PRIMARY KEY (`order_no`)) COMMENT='销售订单临时备份（2025 年初迁移遗留）';
